package shop

import (
	"slices"
	"strings"
	"sync"
)

// Product prices are always integer cents, never floats.
type Product struct {
	ID         string `json:"id"`
	Name       string `json:"name"`
	PriceCents int64  `json:"price_cents"`
	Stock      int    `json:"stock"`
}

// ProductStore is an in-memory, concurrency-safe store of products.
type ProductStore struct {
	mu    sync.RWMutex
	items map[string]Product
	seq   int
}

func NewProductStore() *ProductStore {
	return &ProductStore{items: make(map[string]Product)}
}

// Create assigns the next ID, stores the product, and returns the stored copy.
func (st *ProductStore) Create(p Product) Product {
	st.mu.Lock()
	defer st.mu.Unlock()
	st.seq++
	p.ID = formatID("prd", st.seq)
	st.items[p.ID] = p
	return p
}

func (st *ProductStore) Get(id string) (Product, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	p, ok := st.items[id]
	return p, ok
}

// List returns all products sorted by ID.
func (st *ProductStore) List() []Product {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := make([]Product, 0, len(st.items))
	for _, p := range st.items {
		out = append(out, p)
	}
	slices.SortFunc(out, func(a, b Product) int { return strings.Compare(a.ID, b.ID) })
	return out
}

// AdjustStock adds delta to the product's stock. If the product does not exist or the stock would drop below zero, it returns false and leaves the stock unchanged.
func (st *ProductStore) AdjustStock(id string, delta int) (Product, bool) {
	st.mu.Lock()
	defer st.mu.Unlock()
	p, ok := st.items[id]
	if !ok {
		return p, false
	}
	newStock := p.Stock + delta
	if newStock < 0 {
		return p, false
	}
	p.Stock = newStock
	st.items[id] = p
	return p, true
}

