}

type createUserRequest struct {
	Email string `json:"email"`
	Name  string `json:"name"`
}

func (req createUserRequest) validate() error {
	if req.Email == "" {
		return validationError{"email", "is required"}
	}
	if req.Name == "" {
		return validationError{"name", "is required"}
	}
	return nil
}

func (s *Server) handleListUserOrders(w http.ResponseWriter, r *http.Request) {
	id := r.URL.PathReq("id")
	if id == "" {
		writeError(w, http.StatusNotFound, codeNotFound, "user not found")
		return
	}

	p, err := parsePage(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, codeBadQuery, err.Error())
		return
	}

	items, info := paginate(s.orders.List(), p)

	user, exists := s.users.Get(id)
	if !exists {
		writeError(w, http.StatusNotFound, codeNotFound, fmt.Sprintf("user %s not found", id))
		return
	}

	// Filter orders for this user and sort by ID
	var userOrders []Order
	for _, o := range items {
		if o.UserID == user.ID {
			userOrders = append(userOrders, o)
		}
	}
	slices.SortFunc(userOrders, func(a, b Order) int { return strings.Compare(a.ID, b.ID) })

	writeList(w, userOrders, info)
}

