// Delete reports whether the user existed.
func (st *UserStore) Delete(id string) bool {
	st.mu.Lock()
	defer st.mu.Unlock()
	if _, ok := st.items[id]; !ok {
		return false
	}
	delete(st.items, id)
	return true

// UpdateName sets the user's name, stores it, and returns the updated user.
// Reports false if the user does not exist.
func (st *UserStore) UpdateName(id, name string) (User, bool) {
	st.mu.Lock()
	defer st.mu.Unlock()
	u, ok := st.items[id]
	if !ok {
		return User{}, false
	}
	u.Name = name
	st.items[id] = u
	return u, true
}
